const t = (en: string, hi: string, pa: string): SifLocalizedText => ({ "en-IN": en, "hi-IN": hi, "pa-IN": pa });
const fact = (id: string, text: SifLocalizedText) => ({ id, text });
const candidate = (id: string, text: SifLocalizedText, follows: boolean, strength: SifCandidateAuthority["strength"], supportFactIds: readonly string[], distractorType?: SifCandidateAuthority["distractorType"]): SifCandidateAuthority => ({ id, text, follows, strength, supportFactIds, ...(distractorType ? { distractorType } : {}) });
const guard = { evaluatesSupport: true, assumptionQuestion: false, conclusionQuestion: false, argumentQuestion: false, causeEffectQuestion: false, courseOfActionQuestion: false } as const;

function scenario(input: Omit<SifScenarioAuthority, "identityGuard">): SifScenarioAuthority {
  return { ...input, identityGuard: guard };
}

function supportedScenario(input: {
  readonly id: string;
  readonly cpId: "SIF-CP012" | "SIF-CP013";
  readonly difficulty: SifDifficulty;
  readonly domain: SifScenarioAuthority["domain"];
  readonly mechanism: "SUPPORT_THRESHOLD" | "SCOPE_CONTROL";
  readonly statement: SifLocalizedText;
  readonly facts: readonly { readonly id: string; readonly text: SifLocalizedText }[];
  readonly inferenceI: SifLocalizedText;
  readonly inferenceII: SifLocalizedText;
  readonly supported: "I" | "II";
  readonly explanation: SifLocalizedText;
  readonly distractorType: SifCandidateAuthority["distractorType"];
}): SifScenarioAuthority {
  const supportFacts = input.facts.map((entry) => entry.id);
  return scenario({
    id: input.id,
    cpId: input.cpId,
    difficulty: input.difficulty,
    domain: input.domain,
    mechanisms: [input.mechanism],
    statement: input.statement,
    facts: input.facts,
    candidates: [
      candidate("I", input.inferenceI, input.supported === "I", input.supported === "I" ? "CERTAIN" : "POSSIBLE_ONLY", supportFacts, input.supported === "I" ? undefined : input.distractorType),
      candidate("II", input.inferenceII, input.supported === "II", input.supported === "II" ? "CERTAIN" : "POSSIBLE_ONLY", supportFacts, input.supported === "II" ? undefined : input.distractorType),
    ],
    explanation: input.explanation,
  });
}


